package com.smartsociety.platform.complaint; import com.smartsociety.platform.security.SecurityUser; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/complaints") public class AdminComplaintController {final ComplaintService s;public AdminComplaintController(ComplaintService x){s=x;}@PatchMapping("/{id}/status") public ComplaintDtos.ComplaintResponse status(@PathVariable UUID id,@Valid @RequestBody ComplaintDtos.StatusRequest r,@AuthenticationPrincipal SecurityUser u){return s.status(id,r,u);}@PatchMapping("/{id}/priority") public ComplaintDtos.ComplaintResponse priority(@PathVariable UUID id,@Valid @RequestBody ComplaintDtos.PriorityRequest r,@AuthenticationPrincipal SecurityUser u){return s.priority(id,r,u);} }
